// Package secrets generates credentials and materializes references to them.
//
// A materializer decides how a secret appears in a generated file: inline as
// its value, or as a ${VAR} reference that compose resolves from a .env file.
// Exporters for other platforms add their own materializers later.
package secrets

import (
	"crypto/rand"
	"encoding/base64"
	"fmt"
	"slices"
	"strings"

	"github.com/brian-nunez/breadboard/internal/catalog"
	"github.com/brian-nunez/breadboard/internal/model"
	"github.com/brian-nunez/breadboard/internal/state"
)

// Mode selects a materializer.
type Mode string

const (
	Inline Mode = "inline"
	Dotenv Mode = "dotenv"
)

// ParseMode validates a mode name; empty means Inline.
func ParseMode(s string) (Mode, error) {
	switch Mode(s) {
	case "", Inline:
		return Inline, nil
	case Dotenv:
		return Dotenv, nil
	}
	return "", fmt.Errorf("secret mode %q: must be inline or dotenv", s)
}

// Generate returns a new random value of the given kind.
func Generate(kind catalog.SecretKind) (string, error) {
	switch kind {
	case catalog.ClusterID:
		// Like Kafka's own Uuid.randomUuid, never start with "-": command
		// line tools would read the id as a flag.
		for {
			b := make([]byte, 16)
			if _, err := rand.Read(b); err != nil {
				return "", err
			}
			if id := base64.RawURLEncoding.EncodeToString(b); id[0] != '-' {
				return id, nil
			}
		}
	case catalog.GossipKey:
		b := make([]byte, 32)
		if _, err := rand.Read(b); err != nil {
			return "", err
		}
		return base64.StdEncoding.EncodeToString(b), nil
	default:
		// Base32 (A-Z, 2-7) only, 160 bits: safe in URLs, shell commands,
		// and compose files without escaping.
		return rand.Text() + rand.Text()[:6], nil
	}
}

// Ensure generates every secret the model's infra services need and does not
// have yet. It reports whether anything was added.
func Ensure(m *model.Model, store *state.Secrets) (bool, error) {
	changed := false
	for _, svc := range m.Services {
		if svc.Kind != model.Infra {
			continue
		}
		for _, sec := range svc.Entry.Secrets {
			if _, ok := store.Get(svc.Name, sec.Key); ok {
				continue
			}
			v, err := Generate(sec.Kind)
			if err != nil {
				return false, fmt.Errorf("generate %s secret %s: %w", svc.Name, sec.Key, err)
			}
			store.Set(svc.Name, sec.Key, v)
			changed = true
		}
	}
	return changed, nil
}

// VarName is the .env variable holding a service's secret, e.g.
// POSTGRES__SUPERUSER_PASSWORD. The double underscore separates the service
// from the key, so service "x-superuser" and service "x" never collide.
func VarName(service, key string) string {
	return envName(service) + "__" + envName(key)
}

// EnvPrefixed prefixes an env variable with a service name, e.g.
// ANALYTICS_DATABASE_URL.
func EnvPrefixed(service, name string) string {
	return envName(service) + "_" + name
}

func envName(s string) string {
	return strings.ToUpper(strings.NewReplacer("-", "_", ".", "_").Replace(s))
}

// Materializer renders secret references for one mode and records which
// values a dotenv file must hold.
type Materializer struct {
	mode  Mode
	store *state.Secrets
	used  map[string]string
}

// NewMaterializer returns a materializer over store.
func NewMaterializer(mode Mode, store *state.Secrets) *Materializer {
	return &Materializer{mode: mode, store: store, used: map[string]string{}}
}

// Ref returns how service's secret key appears in a generated file.
func (m *Materializer) Ref(service string) func(key string) string {
	return func(key string) string {
		v, ok := m.store.Get(service, key)
		if !ok {
			panic(fmt.Sprintf("secrets: %s has no secret %q; Ensure must run first", service, key))
		}
		if m.mode == Inline {
			return v
		}
		name := VarName(service, key)
		m.used[name] = v
		return "${" + name + "}"
	}
}

// Dotenv renders the .env file for every reference handed out, or nil in
// inline mode.
func (m *Materializer) Dotenv() []byte {
	if m.mode != Dotenv {
		return nil
	}
	names := make([]string, 0, len(m.used))
	for n := range m.used {
		names = append(names, n)
	}
	slices.Sort(names)
	var b strings.Builder
	b.WriteString("# Generated by bb. Secrets for docker compose; never commit this file.\n")
	for _, n := range names {
		fmt.Fprintf(&b, "%s=%s\n", n, m.used[n])
	}
	return []byte(b.String())
}
